<?php
require_once 'includes/functions.php';
$user = require_login();
$level = level_info((int)$user['xp']);
$q = $pdo->prepare('SELECT COUNT(*) FROM mission_completions WHERE user_id=?'); $q->execute([$user['id']]); $done=(int)$q->fetchColumn();
$total=(int)$pdo->query('SELECT COUNT(*) FROM missions')->fetchColumn();
$recent=$pdo->prepare('SELECT m.title, mc.completed_at FROM mission_completions mc JOIN missions m ON m.id=mc.mission_id WHERE mc.user_id=? ORDER BY mc.completed_at DESC LIMIT 4'); $recent->execute([$user['id']]);
$activity=$pdo->prepare('SELECT la.event_type,la.details,la.occurred_at,m.title FROM learning_activity la LEFT JOIN missions m ON m.id=la.mission_id WHERE la.user_id=? ORDER BY la.occurred_at DESC,la.id DESC LIMIT 8'); $activity->execute([$user['id']]);
$badges=$pdo->prepare('SELECT b.name,b.description FROM user_badges ub JOIN badges b ON b.id=ub.badge_id WHERE ub.user_id=?'); $badges->execute([$user['id']]);
page_header('Agent Dashboard'); show_flash();
?>
<div class="welcome-row"><div><div class="eyebrow">AGENT COMMAND CENTER / 2045</div><h1>Welcome back, <?=e($user['username'])?>.</h1><p class="muted">Shadow Protocol activity has been detected. Your training continues here.</p></div><div class="rank-chip"><span>AGENT RANK</span><strong><?=e($level['rank'])?></strong><small>LEVEL <?= (int)$level['level']?></small></div></div>
<div class="stats-grid"><div class="stat-card"><span>TOTAL EXPERIENCE</span><strong><?= (int)$user['xp']?> XP</strong><small>Level <?= (int)$level['level']?></small></div><div class="stat-card"><span>MISSIONS COMPLETE</span><strong><?=$done?> / <?=$total?></strong><small>Campaign progress</small></div><div class="stat-card"><span>BADGES EARNED</span><strong><?=$badges->rowCount()?></strong><small>Keep collecting</small></div></div>
<section class="panel"><div class="section-head"><div><div class="eyebrow">LEVEL PROGRESSION</div><h2>Agent development</h2></div><strong><?= (int)$level['progress']?> / 500 XP</strong></div><div class="progress"><span style="width:<?=($level['progress']/500)*100?>%"></span></div><p class="muted">Earn XP by completing training missions. First-completion rewards are granted once per mission.</p></section>
<div class="two-col"><section class="panel"><div class="eyebrow">YOUR CAMPAIGN</div><h2>Continue the investigation</h2><p>Choose a mission, examine the evidence and learn why each security decision matters.</p><a class="btn primary" href="missions.php">Open mission map</a></section><section class="panel"><div class="eyebrow">DAILY OPERATIONS</div><h2>Daily challenge</h2><p>Take a short cybersecurity challenge and build a consistent learning habit.</p><a class="btn secondary" href="daily.php">View today's challenge</a></section></div>
<div class="two-col"><section class="panel"><div class="eyebrow">RECENT RECORDS</div><h2>Mission history</h2><?php foreach($recent as $r):?><div class="list-row"><span><?=e($r['title'])?></span><small><?=e($r['completed_at'])?></small></div><?php endforeach;?><?php if($done===0):?><p class="muted">No missions completed yet. Your first mission is waiting.</p><?php endif;?></section><section class="panel"><div class="eyebrow">COLLECTION</div><h2>Achievement badges</h2><?php foreach($badges as $b):?><div class="badge-row"><span class="badge-icon">✦</span><div><strong><?=e($b['name'])?></strong><small><?=e($b['description'])?></small></div></div><?php endforeach;?><?php if($badges->rowCount()===0):?><p class="muted">Complete your first mission to earn a badge.</p><?php endif;?></section></div>
<section class="panel"><div class="eyebrow">YOUR ACTIVITY / VISIBLE TO YOU</div><h2>Recent learning activity</h2><p class="muted">This records room and mission visits, each quiz answer and its approximate response time, quiz submissions, game completions and copilot questions. Quiz camera preview is optional and stays in your browser; no video, gaze, location or other device activity is collected.</p><?php foreach($activity as $item):?><div class="list-row"><span><?=e($item['title']??'Academy')?><small style="display:block"><?=e($item['details'])?></small></span><small><?=e($item['occurred_at'])?></small></div><?php endforeach;?><?php if($activity->rowCount()===0):?><p class="muted">Your learning activity will appear here as you use the academy.</p><?php endif;?></section>
